<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $lease->lease_number }} · LRC LLC</title><style>body{font:15px system-ui;margin:32px;background:#f5f7f8;color:#17212b}main{max-width:850px;margin:auto;background:white;padding:28px;border-radius:14px}label{display:block;margin:10px 0 5px}input,textarea{width:100%;padding:9px;box-sizing:border-box}button{padding:10px 16px;background:#126e66;color:white;border:0;border-radius:6px}.panel{padding:16px;background:#f3f7f6;border-radius:10px;margin:18px 0}</style></head><body><main><p><a href="{{ route('leases.index') }}">← Leases</a></p><h1>{{ $lease->lease_number }}</h1><div class="panel"><strong>{{ ucfirst($lease->status) }}</strong><p>{{ $lease->tenant->legal_name }} · {{ $lease->property->name }} / {{ $lease->unit->unit_code }}</p><p>{{ $lease->starts_on->format('d M Y') }} – {{ $lease->ends_on?->format('d M Y') ?? 'Open-ended' }}</p><p>Rent: {{ number_format((float)$lease->monthly_rent) }} RWF monthly · due day {{ $lease->rent_due_day }}</p><p>Deposit required: {{ number_format((float)$lease->security_deposit_required) }} RWF (tracked separately from rent)</p></div><h2>Recorded lease terms</h2>@foreach($lease->terms as $term)<p>From {{ $term->effective_from->format('d M Y') }}: {{ number_format((float)$term->monthly_rent) }} RWF — {{ $term->change_reason }}</p>@endforeach@if(in_array($lease->status,['draft','approved']))<form method="post" action="{{ route('leases.approve',$lease) }}">@csrf<button>Approve lease</button></form>@endif@if(in_array($lease->status,['approved','active']))<h2>Terminate lease</h2><form method="post" action="{{ route('leases.terminate',$lease) }}">@csrf<label>Termination date</label><input type="date" name="terminated_on" required><label>Reason</label><textarea name="termination_reason" required></textarea><button>Record termination</button></form>@endif</main></body></html>